import{_ as l,a0 as i,w as s,s as a,I as n,x as t,a1 as p,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"米科·哈普寧：開源軟件將使世界更安全 | LCTT x X-CMD","titleTemplate":false,"description":"米科·哈普寧：開源軟件將使世界更安全 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"米科·哈普寧：開源軟件將使世界更安全 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"米科·哈普寧：開源軟件將使世界更安全 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure","title":"米科·哈普寧：開源軟件將使世界更安全","tag":"201311","desc":""},"relativePath":"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure.md","filePath":"[post].md"}'),d={name:"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure.md"};function m(f,e,k,w,T,x){const o=i("Link");return s(),a("div",null,[e[14]||(e[14]=n("h1",{id:"米科·哈普寧-開源軟件將使世界更安全",tabindex:"-1"},[t("米科·哈普寧：開源軟件將使世界更安全 "),n("a",{class:"header-anchor",href:"#米科·哈普寧-開源軟件將使世界更安全","aria-label":"Permalink to “米科·哈普寧：開源軟件將使世界更安全”"},"​")],-1)),n("p",null,[e[1]||(e[1]=t("安全專家米科·哈普寧(Mikko Hypponen)於上週在愛丁堡舉行的",-1)),p(o,{href:"http://events.linuxfoundation.org/events/linuxcon-europe"},{default:r(()=>[...e[0]||(e[0]=[t("LinuxCon and CloudOpen Europe",-1)])]),_:1}),e[2]||(e[2]=t("會議上的主題演講中説：“開源軟件可以作為一個方法來打擊全球監視無辜居民的行為。”",-1))]),e[15]||(e[15]=u('<p><img src="http://www.linux.com/images/stories/41373/Mikko-Hypponen-3.jpg" alt=""></p><p><em>米科·哈普寧，芬蘭F-Secure的首席研究員，在愛丁堡舉行的LinuxCon and CloudOpen Europe 2013會議上講話。</em></p><p>計算和全球網絡增加的進步使得存儲和傳輸數據變得便宜且簡單。哈普寧説這創造了無比的連通性、進步和創新，但是同樣使得大規模的數據被訪問到就像NSA的稜鏡項目揭示的那樣，這事件隨着前美國政府員工愛德華·斯諾登(Edward Snowden)泄漏的一系列頂級機密文件而公開。</p><p>哈普寧，芬蘭F-Secure的首席研究員説：“前幾年我們已經意識到數據是廉價的。我們永遠不必再刪除任何數據。這促成了很多偉大的事情，但同樣也引發了大規模地毯式的監視。”</p><p>哈普寧説：“這些監視會訪問我們的個人數據，包括電話記錄、地理位置、電子郵件和搜索引擎請求，有些可能是被授權的。”</p><p>他説：“我相信一些監控是好的。如果有一項研究來找出校園槍擊者或者毒梟或者恐怖組織成員等等，我們應該已經有技術手段這麼做，但是我們首先必須持有懷疑。”</p><p>哈普寧説：“但是收集通信和每個人的個人數據不僅是對隱私的侵犯，還是對民主的威脅。”</p><p>他説：“即使你如今對政府的行為認可，但是我們不知道政府會在今後的20年怎麼樣。如果他們有你20年的搜索數據，他們會找出一些非法的或者令人尷尬的理由來扭曲你的手。”</p><p>哈普寧説：“雖然泄漏事件使得一些IT專家質疑他們的數據存儲的安全性和經由美國服務商的的路由，但繞開這些公司和服務不能解決問題。同樣不能每個國家都花費和金錢來建造他們自己的替代品。”</p><p>哈普寧説：“要跨越國際邊際地工作，開發者應該團結起來建造一個安全和可靠的軟件和服務來防止後門篡改和用户隱私。”</p><p>他説：“我建議開源軟件對這個問題提供一個解決方案。那麼國家就不必獨自做這件事。這將會變得安全、開放和免費。”</p><hr>',12)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),p(o,{href:"http://www.linux.com/news/featured-blogs/200-libby-clark/745585-mikko-hypponen-open-source-software-will-make-the-world-more-secure"},{default:r(()=>[...e[3]||(e[3]=[t("http://www.linux.com/news/featured-blogs/200-libby-clark/745585-mikko-hypponen-open-source-software-will-make-the-world-more-secure",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=t("譯者：",-1)),p(o,{href:"https://github.com/geekpi"},{default:r(()=>[...e[5]||(e[5]=[t("geekpi",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const g=l(d,[["render",m]]);export{M as __pageData,g as default};
